<script>
(function(){
  'use strict';

  var MAX_EDGE = 1400, JPEG_Q = 0.72, DRAFT_KEY = 'cbs-survey:draft';
  var areasEl   = document.getElementById('areas');
  var siteSel   = document.getElementById('site');
  var siteOther = document.getElementById('site-other');
  var raisedEl  = document.getElementById('raised');
  var surveyEl  = document.getElementById('surveyor');
  var dateEl    = document.getElementById('date');
  var conditionsEl = document.getElementById('conditions');
  var jobEl     = document.getElementById('jobno');
  var toastEl   = document.getElementById('toast');
  var lightbox  = document.getElementById('lightbox');
  var lbImg     = document.getElementById('lb-img');

  var areas = [], seq = 0, toastTimer = null;

  dateEl.value = new Date().toISOString().slice(0,10);

  // the logo ships once; the print header reuses the same data URI
  var logo = document.getElementById('logo');
  var LOGO_SRC = logo.getAttribute('src');
  document.querySelector('.print-head img').src = LOGO_SRC;

  // if the logo fails to decode, fall back to a wordmark
  logo.addEventListener('error', function(){
    var span = document.createElement('span');
    span.className = 'wordmark';
    span.textContent = 'CHELMSFORD BUILDING SERVICES LTD';
