  var downloads = null;
  if (window.claude && typeof window.claude.use === 'function'){
    try{
      Promise.resolve(window.claude.use('downloads')).then(function(d){ downloads = d; }, function(){});
    }catch(e){}
  }

  function uid(){ return 'a' + (++seq) + '-' + Date.now().toString(36); }

  function toast(msg, bad){
    toastEl.textContent = msg;
    toastEl.className = 'toast' + (bad ? ' bad' : '');
    toastEl.hidden = false;
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function(){ toastEl.hidden = true; }, 3200);
  }

  function jobNo(){ var m = String(jobEl.value || '').match(/[0-9A-Za-z-]+/); return m ? m[0] : ''; }
  function siteValue(){ return siteSel.value === '__other' ? siteOther.value.trim() : siteSel.value; }

  function el(tag, cls, text){
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text != null) n.textContent = text;
    return n;
  }

  /* ---------- area blocks ---------- */
  function addArea(data){
    var area = { id: uid(), name: (data && data.name) || '', scope: (data && data.scope) || '', remedial: (data && data.remedial) || '', photos: [] };
    var wrap = el('section','block area');

    var head = el('div','area-head');
    var no = el('span','area-no','1');
    var title = el('h3',null,'Area');
    var del = el('button','link-btn','Remove');
    del.type = 'button';
    head.appendChild(no); head.appendChild(title); head.appendChild(del);

    var f1 = el('div','field');
    var l1 = el('label',null,'Area '); l1.appendChild(el('span','req','*'));
    var i1 = document.createElement('input');
    i1.type = 'text'; i1.placeholder = 'e.g. Syrup room, Line 3 canopy, Roof plant'; i1.value = area.name;
    l1.setAttribute('for', area.id + '-name'); i1.id = area.id + '-name';
    f1.appendChild(l1); f1.appendChild(i1);

    var f2 = el('div','field');
    var l2 = el('label',null,'Scope of works '); l2.appendChild(el('span','req','*'));
    var t2 = document.createElement('textarea');
    t2.placeholder = 'What needs doing, condition found, access notes, materials, anything affecting price.';
    t2.value = area.scope;
    l2.setAttribute('for', area.id + '-scope'); t2.id = area.id + '-scope';
    f2.appendChild(l2); f2.appendChild(t2);

    var f3 = el('div','field');
    var l3 = el('label',null,'Photographs');
    var tap = el('button','photo-tap');
    tap.type = 'button';
    tap.innerHTML = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M3 8h3.5L8 6h8l1.5 2H21v11H3z"/><circle cx="12" cy="13.5" r="3.6"/></svg><span>Take or choose photos</span>';
    var input = document.createElement('input');
    input.type = 'file'; input.accept = 'image/*'; input.multiple = true;
    // no capture attribute: it forces the camera and removes the
    // photo-library and file options, so existing photos can't be picked.
    // Visually hidden rather than display:none — a display:none input
    // cannot be opened by a scripted .click() in some mobile browsers.
    input.style.cssText = 'position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);clip-path:inset(50%);white-space:nowrap;border:0';
    var thumbs = el('div','thumbs');
    var count = el('p','count','No photographs yet');
    f3.appendChild(l3); f3.appendChild(tap); f3.appendChild(input); f3.appendChild(thumbs); f3.appendChild(count);

    var f4 = el('div','field');
    var l4 = el('label',null,'Recommended remedial works');
    var t4 = document.createElement('textarea');
    t4.placeholder = 'What CBS recommends doing, priority, and anything to flag to the client.';
    t4.value = area.remedial;
    l4.setAttribute('for', area.id + '-rem'); t4.id = area.id + '-rem';
    f4.appendChild(l4); f4.appendChild(t4);

    wrap.appendChild(head); wrap.appendChild(f1); wrap.appendChild(f2); wrap.appendChild(f3); wrap.appendChild(f4);
    areasEl.appendChild(wrap);

    area.el = wrap; area.nameInput = i1; area.scopeInput = t2; area.remedialInput = t4;
    area.thumbs = thumbs; area.count = count; area.noEl = no; area.titleEl = title;
    areas.push(area);

    i1.addEventListener('input', function(){
      area.name = i1.value; i1.classList.remove('invalid');
      title.textContent = i1.value.trim() || 'Area';
      saveDraft();
    });
    t2.addEventListener('input', function(){ area.scope = t2.value; t2.classList.remove('invalid'); saveDraft(); });
    t4.addEventListener('input', function(){ area.remedial = t4.value; saveDraft(); });
    tap.addEventListener('click', function(){ input.click(); });
    input.addEventListener('change', function(){ handleFiles(area, input.files); input.value = ''; });
    del.addEventListener('click', function(){ removeArea(area, del); });

    renumber(); tally();
    if (!data) i1.focus();
    return area;
  }

  function removeArea(area, btn){
    if (areas.length === 1){ toast('A survey needs at least one area.', true); return; }
    if (btn.getAttribute('data-armed') !== '1'){
      btn.setAttribute('data-armed','1');
      btn.textContent = 'Confirm remove';
      btn.style.fontWeight = '700';
      setTimeout(function(){
        if (btn.getAttribute('data-armed') === '1'){
          btn.setAttribute('data-armed','0'); btn.textContent = 'Remove'; btn.style.fontWeight = '600';
        }
      }, 5000);
      return;
    }
    area.el.remove();
    areas = areas.filter(function(a){ return a !== area; });
    renumber(); tally(); saveDraft();
    toast('Area removed.');
  }

  function renumber(){ areas.forEach(function(a,i){ a.noEl.textContent = String(i+1); }); }

  /* ---------- photos ---------- */
  function handleFiles(area, files){
    var list = Array.prototype.slice.call(files || []);
    if (!list.length) return;
    var done = 0;
    list.forEach(function(file){
      if (!/^image\//.test(file.type)) { done++; return; }
      shrink(file, function(src, w, h){
        if (src) area.photos.push({ id: uid(), src: src, w: w || 4, h: h || 3 });
        done++;
        if (done === list.length) renderThumbs(area);
      });
    });
  }

  function shrink(file, cb){
    var reader = new FileReader();
    reader.onload = function(){
