    .p-area p{margin:0 0 6px; white-space:pre-wrap}
    .p-area .p-lab{font-size:8.5pt; letter-spacing:.12em; text-transform:uppercase; color:#666; margin:4mm 0 2px}
    .p-photos{display:grid; grid-template-columns:repeat(3,1fr); gap:4mm}
    .p-photos img{width:100%; height:44mm; object-fit:cover; border:1px solid #999}
    .p-foot{margin-top:6mm; padding-top:4mm; border-top:1px solid #ea6810; font-size:8.5pt; color:#666}
  }
  @media (prefers-reduced-motion:reduce){*{transition:none !important; animation:none !important}}
</style>

