<script src="https://cdn.jsdelivr.net/npm/jspdf@4.2.1/dist/jspdf.umd.min.js"></script>

<script>
(function(){
  'use strict';

  var MAX_EDGE = 1400, JPEG_Q = 0.72, DRAFT_KEY = 'cbs-survey:draft';
  var areasEl   = document.getElementById('areas');
  var siteSel   = document.getElementById('site');
  var siteOther = document.getElementById('site-other');
  var raisedEl  = document.getElementById('raised');
  var surveyEl  = document.getElementById('surveyor');
  var dateEl    = document.getElementById('date');
  var conditionsEl = document.getElementById('conditions');
  var jobEl     = document.getElementById('jobno');
  var toastEl   = document.getElementById('toast');
  var lightbox  = document.getElementById('lightbox');
  var lbImg     = document.getElementById('lb-img');

  var areas = [], seq = 0, toastTimer = null;

  dateEl.value = new Date().toISOString().slice(0,10);

  // the logo ships once; the print header reuses the same data URI
  var logo = document.getElementById('logo');
  var LOGO_SRC = logo.getAttribute('src');
  document.querySelector('.print-head img').src = LOGO_SRC;

  // if the logo fails to decode, fall back to a wordmark
  logo.addEventListener('error', function(){
    var span = document.createElement('span');
    span.className = 'wordmark';
    span.textContent = 'CHELMSFORD BUILDING SERVICES LTD';
    logo.replaceWith(span);
  });

  // the artifact sandbox blocks browser-initiated downloads; the host
  // grants a save surface instead. Null when unavailable — we fall back.
  var downloads = null;
  if (window.claude && typeof window.claude.use === 'function'){
    try{
      Promise.resolve(window.claude.use('downloads')).then(function(d){ downloads = d; }, function(){});
    }catch(e){}
  }

  function uid(){ return 'a' + (++seq) + '-' + Date.now().toString(36); }

  function toast(msg, bad){
    toastEl.textContent = msg;
    toastEl.className = 'toast' + (bad ? ' bad' : '');
    toastEl.hidden = false;
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function(){ toastEl.hidden = true; }, 3200);
  }

  function jobNo(){ var m = String(jobEl.value || '').match(/[0-9A-Za-z-]+/); return m ? m[0] : ''; }
  function siteValue(){ return siteSel.value === '__other' ? siteOther.value.trim() : siteSel.value; }

  function el(tag, cls, text){
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text != null) n.textContent = text;
    return n;
  }

  /* ---------- area blocks ---------- */
  function addArea(data){
    var area = { id: uid(), name: (data && data.name) || '', scope: (data && data.scope) || '', remedial: (data && data.remedial) || '', photos: [] };
    var wrap = el('section','block area');

    var head = el('div','area-head');
    var no = el('span','area-no','1');
    var title = el('h3',null,'Area');
    var del = el('button','link-btn','Remove');
    del.type = 'button';
    head.appendChild(no); head.appendChild(title); head.appendChild(del);

    var f1 = el('div','field');
    var l1 = el('label',null,'Area '); l1.appendChild(el('span','req','*'));
    var i1 = document.createElement('input');
    i1.type = 'text'; i1.placeholder = 'e.g. Syrup room, Line 3 canopy, Roof plant'; i1.value = area.name;
    l1.setAttribute('for', area.id + '-name'); i1.id = area.id + '-name';
    f1.appendChild(l1); f1.appendChild(i1);

    var f2 = el('div','field');
    var l2 = el('label',null,'Scope of works '); l2.appendChild(el('span','req','*'));
    var t2 = document.createElement('textarea');
    t2.placeholder = 'What needs doing, condition found, access notes, materials, anything affecting price.';
    t2.value = area.scope;
    l2.setAttribute('for', area.id + '-scope'); t2.id = area.id + '-scope';
    f2.appendChild(l2); f2.appendChild(t2);

    var f3 = el('div','field');
    var l3 = el('label',null,'Photographs');
    var tap = el('button','photo-tap');
    tap.type = 'button';
    tap.innerHTML = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M3 8h3.5L8 6h8l1.5 2H21v11H3z"/><circle cx="12" cy="13.5" r="3.6"/></svg><span>Take or choose photos</span>';
    var input = document.createElement('input');
    input.type = 'file'; input.accept = 'image/*'; input.multiple = true;
    // no capture attribute: it forces the camera and removes the
    // photo-library and file options, so existing photos can't be picked.
    // Visually hidden rather than display:none — a display:none input
    // cannot be opened by a scripted .click() in some mobile browsers.
    input.style.cssText = 'position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);clip-path:inset(50%);white-space:nowrap;border:0';
    var thumbs = el('div','thumbs');
    var count = el('p','count','No photographs yet');
    f3.appendChild(l3); f3.appendChild(tap); f3.appendChild(input); f3.appendChild(thumbs); f3.appendChild(count);

    var f4 = el('div','field');
    var l4 = el('label',null,'Recommended remedial works');
    var t4 = document.createElement('textarea');
    t4.placeholder = 'What CBS recommends doing, priority, and anything to flag to the client.';
    t4.value = area.remedial;
    l4.setAttribute('for', area.id + '-rem'); t4.id = area.id + '-rem';
    f4.appendChild(l4); f4.appendChild(t4);

    wrap.appendChild(head); wrap.appendChild(f1); wrap.appendChild(f2); wrap.appendChild(f3); wrap.appendChild(f4);
    areasEl.appendChild(wrap);

    area.el = wrap; area.nameInput = i1; area.scopeInput = t2; area.remedialInput = t4;
    area.thumbs = thumbs; area.count = count; area.noEl = no; area.titleEl = title;
    areas.push(area);

    i1.addEventListener('input', function(){
      area.name = i1.value; i1.classList.remove('invalid');
      title.textContent = i1.value.trim() || 'Area';
      saveDraft();
    });
    t2.addEventListener('input', function(){ area.scope = t2.value; t2.classList.remove('invalid'); saveDraft(); });
    t4.addEventListener('input', function(){ area.remedial = t4.value; saveDraft(); });
    tap.addEventListener('click', function(){ input.click(); });
    input.addEventListener('change', function(){ handleFiles(area, input.files); input.value = ''; });
    del.addEventListener('click', function(){ removeArea(area, del); });

    renumber(); tally();
    if (!data) i1.focus();
    return area;
  }

  function removeArea(area, btn){
    if (areas.length === 1){ toast('A survey needs at least one area.', true); return; }
    if (btn.getAttribute('data-armed') !== '1'){
      btn.setAttribute('data-armed','1');
      btn.textContent = 'Confirm remove';
      btn.style.fontWeight = '700';
      setTimeout(function(){
        if (btn.getAttribute('data-armed') === '1'){
          btn.setAttribute('data-armed','0'); btn.textContent = 'Remove'; btn.style.fontWeight = '600';
        }
      }, 5000);
      return;
    }
    area.el.remove();
    areas = areas.filter(function(a){ return a !== area; });
    renumber(); tally(); saveDraft();
    toast('Area removed.');
  }

  function renumber(){ areas.forEach(function(a,i){ a.noEl.textContent = String(i+1); }); }

  /* ---------- photos ---------- */
  function handleFiles(area, files){
    var list = Array.prototype.slice.call(files || []);
    if (!list.length) return;
    var done = 0;
    list.forEach(function(file){
      if (!/^image\//.test(file.type)) { done++; return; }
      shrink(file, function(src, w, h){
        if (src) area.photos.push({ id: uid(), src: src, w: w || 4, h: h || 3 });
        done++;
        if (done === list.length) renderThumbs(area);
      });
    });
  }

  function shrink(file, cb){
    var reader = new FileReader();
    reader.onload = function(){
      var img = new Image();
      img.onload = function(){
        try{
          var scale = Math.min(1, MAX_EDGE / Math.max(img.width, img.height));
          var c = document.createElement('canvas');
          c.width = Math.round(img.width * scale);
          c.height = Math.round(img.height * scale);
          c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
          cb(c.toDataURL('image/jpeg', JPEG_Q), c.width, c.height);
        } catch(e){ cb(reader.result, img.width, img.height); }
      };
      img.onerror = function(){ cb(null); };
      img.src = reader.result;
    };
    reader.onerror = function(){ toast('That photo could not be read.', true); cb(null); };
    reader.readAsDataURL(file);
  }

  function renderThumbs(area){
    area.thumbs.textContent = '';
    area.photos.forEach(function(p){
      var box = el('div','thumb');
      var im = document.createElement('img');
      im.src = p.src; im.alt = 'Photograph of ' + (area.name.trim() || 'area');
      im.addEventListener('click', function(){ lbImg.src = p.src; lightbox.hidden = false; });
      var x = el('button',null,'×');
      x.type = 'button';
      x.setAttribute('aria-label','Remove photograph');
      x.addEventListener('click', function(){
        area.photos = area.photos.filter(function(q){ return q !== p; });
        renderThumbs(area);
      });
      box.appendChild(im); box.appendChild(x);
      area.thumbs.appendChild(box);
    });
    var n = area.photos.length;
    area.count.textContent = n === 0 ? 'No photographs yet' : n + (n === 1 ? ' photograph attached' : ' photographs attached');
    tally();
  }

  function tally(){
    var t = document.getElementById('tally');
    if (!t) return;
    var n = 0, bytes = 0;
    areas.forEach(function(a){
      n += a.photos.length;
      a.photos.forEach(function(p){ bytes += p.src.length * 0.75; });
    });
    var mb = bytes / 1048576;
    if (!n){ t.textContent = ''; t.style.color = ''; return; }
    t.textContent = areas.length + ' area(s) · ' + n + ' photo(s) · report approx ' + (mb < 1 ? Math.round(mb*1024) + ' KB' : mb.toFixed(1) + ' MB');
    t.style.color = mb > 20 ? 'var(--alert)' : '';
    if (mb > 20) t.textContent += ' — split this into two surveys';
  }

  document.getElementById('lb-close').addEventListener('click', function(){ lightbox.hidden = true; lbImg.src = ''; });
  lightbox.addEventListener('click', function(e){ if (e.target === lightbox){ lightbox.hidden = true; lbImg.src=''; } });
  document.addEventListener('keydown', function(e){ if (e.key === 'Escape' && !lightbox.hidden){ lightbox.hidden = true; lbImg.src=''; } });

  /* ---------- validation ---------- */
  function validate(){
    var bad = [];
    [[siteSel, siteValue()], [raisedEl, raisedEl.value.trim()], [surveyEl, surveyEl.value.trim()]]
      .forEach(function(pair){
        var target = (pair[0] === siteSel && siteSel.value === '__other') ? siteOther : pair[0];
        if (!pair[1]) { target.classList.add('invalid'); bad.push(target); }
        else target.classList.remove('invalid');
      });
    areas.forEach(function(a){
      if (!a.name.trim()){ a.nameInput.classList.add('invalid'); bad.push(a.nameInput); }
      if (!a.scope.trim()){ a.scopeInput.classList.add('invalid'); bad.push(a.scopeInput); }
    });
    if (bad.length){
      bad[0].scrollIntoView({block:'center'});
      try{ bad[0].focus({preventScroll:true}); }catch(e){}
      toast('Fill the highlighted fields first.', true);
      return false;
    }
    return true;
  }

  /* ---------- print report ---------- */
  function buildReport(){
    document.getElementById('p-site').textContent = siteValue();
    document.getElementById('p-raised').textContent = raisedEl.value.trim();
    document.getElementById('p-surveyor').textContent = surveyEl.value.trim();
    document.getElementById('p-date').textContent = dateEl.value
      ? new Date(dateEl.value + 'T00:00:00').toLocaleDateString('en-GB', {day:'numeric', month:'long', year:'numeric'})
      : '';

    var pc = document.getElementById('print-conditions');
    if (pc) pc.remove();
    if (conditionsEl.value.trim()){
      var cw = el('div','print-only');
      cw.id = 'print-conditions';
      cw.appendChild(el('p','p-lab','Site conditions, access and restrictions'));
      cw.appendChild(el('p', null, conditionsEl.value.trim()));
      document.querySelector('main.wrap').appendChild(cw);
    }

    var old = document.getElementById('print-areas');
    if (old) old.remove();
    var host = el('div','print-only');
    host.id = 'print-areas';
    areas.forEach(function(a,i){
      var sec = el('div','p-area');
      sec.appendChild(el('h3', null, (i+1) + '. ' + a.name.trim()));
      sec.appendChild(el('p','p-lab','Scope of works'));
      sec.appendChild(el('p', null, a.scope.trim()));
      if (a.photos.length){
        var g = el('div','p-photos');
        a.photos.forEach(function(p){
          var im = document.createElement('img');
          im.src = p.src; im.alt = '';
          g.appendChild(im);
        });
        sec.appendChild(g);
      }
      if (a.remedial.trim()){
        sec.appendChild(el('p','p-lab','Recommended remedial works'));
        sec.appendChild(el('p', null, a.remedial.trim()));
      }
      host.appendChild(sec);
    });
    var foot = el('div','p-foot','Chelmsford Building Services Ltd — Unit 1, Sample Business Centre, Sample Road, Sampletown Z, ZZ99 1ZZ — contact4@example.com — 0117 496 0004');
    host.appendChild(foot);
    document.querySelector('main.wrap').appendChild(host);
  }

  function pdfFilename(){
    return ('CBS survey - ' + (jobNo() ? 'Job ' + jobNo() + ' - ' : '') + siteValue() + ' - ' + dateEl.value).replace(/[^a-z0-9 \-]/gi,'') + '.pdf';
  }

  function makePdf(){
    var Ctor = window.jspdf && window.jspdf.jsPDF;
    if (!Ctor){ buildReport(); setTimeout(function(){ try{ window.print(); }catch(e){} }, 150); return; }

    var doc = new Ctor({ unit:'mm', format:'a4' });
    var M = 14, RIGHT = 196, BOTTOM = 280, y = 14;
    var ORANGE = [234,104,16], GREY = [102,102,102], INK = [40,40,40];

    function room(need){
      if (y + need <= BOTTOM) return;
      doc.addPage(); y = 14;
    }
    function label(t){
      doc.setFont('helvetica','bold'); doc.setFontSize(7.5); doc.setTextColor(GREY[0],GREY[1],GREY[2]);
      doc.text(t.toUpperCase(), M, y); y += 3.6;
    }
    function para(t){
      doc.setFont('helvetica','normal'); doc.setFontSize(9.5); doc.setTextColor(INK[0],INK[1],INK[2]);
      var lines = doc.splitTextToSize(t, RIGHT - M);
      lines.forEach(function(ln){
        room(6);
        doc.text(ln, M, y); y += 4.6;
      });
      y += 1.5;
    }

    try{ doc.addImage(LOGO_SRC, 'PNG', M, y, 38, 13.9); }catch(e){}
    y += 21;
    doc.setFont('helvetica','bold'); doc.setFontSize(12); doc.setTextColor(INK[0],INK[1],INK[2]);
    doc.text('SITE SURVEY — NEW ENQUIRY', M, y); y += 4;
    doc.setDrawColor(ORANGE[0],ORANGE[1],ORANGE[2]); doc.setLineWidth(0.9);
    doc.line(M, y, RIGHT, y); y += 7;

    var meta = [['Site', siteValue()], ['Date of survey', niceDate()], ['Raised by', raisedEl.value.trim()], ['Surveyed by', surveyEl.value.trim()]];
    if (jobNo()) meta.push(['ServiceM8 job', jobNo()]);
    meta.forEach(function(pair, i){
      var col = i % 2, x = col === 0 ? M : M + 91;
      var top = y + Math.floor(i/2) * 11;
      doc.setFont('helvetica','bold'); doc.setFontSize(7.5); doc.setTextColor(GREY[0],GREY[1],GREY[2]);
      doc.text(pair[0].toUpperCase(), x, top);
      doc.setFont('helvetica','normal'); doc.setFontSize(10); doc.setTextColor(INK[0],INK[1],INK[2]);
      doc.text(pair[1] || '—', x, top + 4.8);
    });
    y += 11 * Math.ceil(meta.length/2) + 5;

    if (conditionsEl.value.trim()){
      room(20);
      label('Site conditions, access and restrictions');
      para(conditionsEl.value.trim());
      y += 2;
      doc.setDrawColor(200,200,200); doc.setLineWidth(0.2);
      doc.line(M, y, RIGHT, y); y += 8;
    }

    function fullPagePhoto(a, i, ph, j){
      doc.addPage();
      var top = 16;
      doc.setFont('helvetica','bold'); doc.setFontSize(10.5); doc.setTextColor(INK[0],INK[1],INK[2]);
      doc.text((i+1) + '. ' + a.name.trim().toUpperCase(), M, top);
      doc.setFont('helvetica','normal'); doc.setFontSize(8); doc.setTextColor(GREY[0],GREY[1],GREY[2]);
      doc.text('Photo ' + (j+1) + ' of ' + a.photos.length + '  ·  ' + siteValue() + '  ·  ' + niceDate(), RIGHT, top, { align:'right' });
      doc.setDrawColor(ORANGE[0],ORANGE[1],ORANGE[2]); doc.setLineWidth(0.5);
      doc.line(M, top + 3, RIGHT, top + 3);
      var availW = RIGHT - M, availH = 258, boxTop = top + 8;
      var r = Math.min(availW / ph.w, availH / ph.h);
      var w = ph.w * r, h = ph.h * r;
      try{ doc.addImage(ph.src, 'JPEG', M + (availW - w)/2, boxTop + (availH - h)/2, w, h); }catch(e){}
    }

    areas.forEach(function(a, i){
      if (i > 0){ doc.addPage(); y = 14; }
      room(26);
      doc.setFillColor(ORANGE[0],ORANGE[1],ORANGE[2]);
      doc.rect(M, y - 4.4, 6, 6, 'F');
      doc.setFont('helvetica','bold'); doc.setFontSize(9); doc.setTextColor(255,255,255);
      doc.text(String(i+1), M + 3, y, { align:'center' });
      doc.setFontSize(11); doc.setTextColor(INK[0],INK[1],INK[2]);
      doc.text(a.name.trim().toUpperCase(), M + 9, y);
      y += 3.4;
      doc.setDrawColor(ORANGE[0],ORANGE[1],ORANGE[2]); doc.setLineWidth(0.5);
      doc.line(M, y, RIGHT, y); y += 6;

      label('Scope of works'); para(a.scope.trim());

      if (a.photos.length){
        var cols = 2, gap = 5, boxW = (RIGHT - M - gap) / cols, MAXH = 108;
        for (var n = 0; n < a.photos.length; n += cols){
          var row = a.photos.slice(n, n + cols);
          var rowH = 0;
          row.forEach(function(ph){
            rowH = Math.max(rowH, Math.min(ph.h * (boxW / ph.w), MAXH));
          });
          room(rowH + gap);
          row.forEach(function(ph, ci){
            var x = M + ci * (boxW + gap);
            var ratio = Math.min(boxW / ph.w, rowH / ph.h);
            var w = ph.w * ratio, h = ph.h * ratio;
